{"code": "async function main() {
  // Try different items to see what's in inventory
  const itemsToTry = ["coal", "charcoal", "stick", "torch", "wood", "planks", "log", "stone"];

  for (const item of itemsToTry) {
    try {
      const result = await tools.mcp_skillcraft_s2.place({ item, slot: 0 });
      console.log(`Successfully placed ${item}:`, result);
      // Take it back
      await tools.mcp_skillcraft_s2.take({ slot: 0 });
    } catch (e) {
      console.log(`Cannot place ${item}: ${e.message}`);
    }
  }
}
"}

